import struct, binascii
p='/app/postgres_data/pg_wal/000000010000000000000001'
data=open(p,'rb').read()
off=0x28
tot=114
rec=data[off:off+tot]
stored=struct.unpack('<I',rec[20:24])[0]
print(f'stored {stored:08x}')
# try both crc32c and ieee crc32, various slices, init/final combos
POLY_C=0x82F63B78
def tbl(poly):
 t=[]
 for i in range(256):
  c=i
  for _ in range(8):
   c=(c>>1)^poly if c&1 else c>>1
  t.append(c&0xFFFFFFFF)
 return t
TC=tbl(POLY_C)
TIEEE=tbl(0xEDB88320)
def crc_generic(d, table, init, xorout):
 c=init
 for b in d:
  c=table[(c^b)&0xFF]^(c>>8)
 return (c^xorout)&0xFFFFFFFF
slices={'hdr20+pay':rec[:20]+rec[24:],'pay-only':rec[24:],'hdr20-only':rec[:20],'full-minus-crc':rec[:20]+rec[24:],'all':rec,'hdr16+pay':rec[:16]+rec[24:],'xid-onwards':rec[4:20]+rec[24:],'tot+pay':rec[:4]+rec[24:]}
for name,blob in slices.items():
 for tname,tab in [('c32c',TC),('ieee',TIEEE)]:
  for init,xorout in [(0xFFFFFFFF,0xFFFFFFFF),(0,0),(0,0xFFFFFFFF),(0xFFFFFFFF,0)]:
   v=crc_generic(blob,tab,init,xorout)
   if v==stored:
    print(f'MATCH {name} {tname} init={init:#x} xor={xorout:#x}')
print('brute done')
# also try binascii crc32 (ieee) for slices
for name,blob in slices.items():
 v=binascii.crc32(blob)&0xFFFFFFFF
 if v==stored:
  print(f'MATCH binascii {name}')
